nfiguration_key,'MIGRATION_READY','ARCHITECTURE_APPROVED','MIGRATION_READY','v41-c3r2k-core-observability-recovery-incident-consumer-closure','C3R2K typed runtime consumer implemented; Single Authority cutover remains pending',source_observation_hash,'{"stage":"V41_C3R2K_CORE_OBSERVABILITY_RECOVERY_INCIDENT_CONSUMER_CLOSURE","cutover":"NOT_FINALIZED"}'::jsonb from advanced;
do $$ declare v_governance_ready integer; begin select count(*) into v_governance_ready from runtime_config_inventory_governance where configuration_key in ('core.lifecycle.incident.inactive-threshold','core.lifecycle.incident.max-batch-size','core.lifecycle.incident.reopen-policy','core.lifecycle.incident.reopen-window','core.lifecycle.incident.scan-interval-ms','core.observability.business-metrics-enabled','core.observability.common-tags.component','core.observability.enabled','core.observability.health-indicator-enabled','core.observability.include-site-tag','core.observability.recovery-metrics.dead-letter-critical-threshold','core.observability.recovery-metrics.dead-letter-warning-threshold','core.observability.recovery-metrics.delayed-requeue-critical-threshold','core.observability.recovery-metrics.delayed-requeue-warning-threshold','core.observability.recovery-metrics.enabled','core.observability.recovery-metrics.history-limit','core.observability.recovery-metrics.recovery-exhausted-critical-threshold','core.observability.recovery-metrics.recovery-exhausted-warning-threshold','core.observability.recovery-metrics.runtime-failure-critical-threshold','core.observability.recovery-metrics.runtime-failure-warning-threshold','core.observability.recovery-metrics.scanner-failure-critical-threshold','core.observability.recovery-metrics.scanner-failure-warning-threshold','core.observability.recovery-metrics.window','core.observability.slow-intake-threshold','core.observability.summary-sample-limit') and status='MIGRATION_READY' and classified_by is not null and owner_reviewed_by is not null and architecture_approved_by is not null and migration_authorized_by='v41-c3r2k-core-observability-recovery-incident-consumer-closure'; if v_governance_ready<>25 then raise exception 'C3R2K_GOVERNANCE_LIFECYCLE_INCOMPLETE expected=25 actual=%',v_governance_ready; end if; end $$;

do $$ declare v_ready integer; begin
select count(*) into v_ready from runtime_config_definitions where definition_key in ('core.lifecycle.incident.inactive-threshold','core.lifecycle.incident.max-batch-size','core.lifecycle.incident.reopen-policy','core.lifecycle.incident.reopen-window','core.lifecycle.incident.scan-interval-ms','core.observability.business-metrics-enabled','core.observability.common-tags.component','core.observability.enabled','core.observability.health-indicator-enabled','core.observability.include-site-tag','core.observability.recovery-metrics.dead-letter-critical-threshold','core.observability.recovery-metrics.dead-letter-warning-threshold','core.observability.recovery-metrics.delayed-requeue-critical-threshold','core.observability.recovery-metrics.delayed-requeue-warning-threshold','core.observability.recovery-metrics.enabled','core.observability.recovery-metrics.history-limit','core.observability.recovery-metrics.recovery-exhausted-critical-threshold','core.observability.recovery-metrics.recovery-exhausted-warning-threshold','core.observability.recovery-metrics.runtime-failure-critical-threshold','core.observability.recovery-metrics.runtime-failure-warning-threshold','core.observability.recovery-metrics.scanner-failure-critical-threshold','core.observability.recovery-metrics.scanner-failure-warning-threshold','core.observability.recovery-metrics.window','core.observability.slow-intake-threshold','core.observability.summary-sample-limit') and review_status='MIGRATION_READY' and migration_authorized=true and admin_editable=true;
if v_ready<>25 then raise exception 'C3R2K_DOMAIN_DEFINITION_CLOSURE_INCOMPLETE expected=25 actual=%',v_ready; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.observability.include-tenant-tag','core.recovery.governance.allow-body-operator-id-override','core.recovery.governance.approval-confirmation-phrase','core.recovery.governance.approval-ttl','core.recovery.governance.enabled','core.recovery.governance.forbid-self-approval','core.recovery.governance.high-risk-confirmation-phrase','core.recovery.governance.min-reason-length','core.recovery.governance.moderate-confirmation-phrase','core.recovery.governance.require-confirmation','core.recovery.governance.require-dual-control-for-high-risk','core.recovery.governance.require-reason') and (migration_authorized=true or admin_editable=true)) then raise exception 'C3R2K_NON_RUNTIME_AUTHORITY_LEAK'; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.recovery.governance.allow-body-operator-id-override','core.recovery.governance.approval-confirmation-phrase','core.recovery.governance.approval-ttl','core.recovery.governance.enabled','core.recovery.governance.forbid-self-approval','core.recovery.governance.high-risk-confirmation-phrase','core.recovery.governance.min-reason-length','core.recovery.governance.moderate-confirmation-phrase','core.recovery.governance.require-confirmation','core.recovery.governance.require-dual-control-for-high-risk','core.recovery.governance.require-reason') and authority_class<>'SECURITY_INVARIANT') then raise exception 'C3R2K_RECOVERY_GOVERNANCE_SECURITY_CLASSIFICATION_MISSING'; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.observability.business-metrics-enabled','core.observability.common-tags.component','core.observability.enabled','core.observability.health-indicator-enabled','core.observability.include-site-tag','core.observability.recovery-metrics.dead-letter-critical-threshold','core.observability.recovery-metrics.dead-letter-warning-threshold','core.observability.recovery-metrics.delayed-requeue-critical-threshold','core.observability.recovery-metrics.delayed-requeue-warning-threshold','core.observability.recovery-metrics.enabled','core.observability.recovery-metrics.history-limit','core.observability.recovery-metrics.recovery-exhausted-critical-threshold','core.observability.recovery-metrics.recovery-exhausted-warning-threshold','core.observability.recovery-metrics.runtime-failure-critical-threshold','core.observability.recovery-metrics.runtime-failure-warning-threshold','core.observability.recovery-metrics.scanner-failure-critical-threshold','core.observability.recovery-metrics.scanner-failure-warning-threshold','core.observability.recovery-metrics.window','core.observability.slow-intake-threshold','core.observability.summary-sample-limit') and config_set_key<>'RUNTIME/CORE/SYSTEM') then raise exception 'C3R2K_CORE_CONFIG_SET_KEY_MISMATCH'; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.lifecycle.incident.inactive-threshold','core.lifecycle.incident.max-batch-size','core.lifecycle.incident.reopen-policy','core.lifecycle.incident.reopen-window','core.lifecycle.incident.scan-interval-ms') and config_set_key<>'RUNTIME/INCIDENT/SYSTEM') then raise exception 'C3R2K_INCIDENT_CONFIG_SET_KEY_MISMATCH'; end if;
if exists(select 1 from runtime_config_inventory_governance where configuration_key in ('core.lifecycle.incident.inactive-threshold','core.lifecycle.incident.max-batch-size','core.lifecycle.incident.reopen-policy','core.lifecycle.incident.reopen-window','core.lifecycle.incident.scan-interval-ms','core.observability.business-metrics-enabled','core.observability.common-tags.component','core.observability.enabled','core.observability.health-indicator-enabled','core.observability.include-site-tag','core.observability.recovery-metrics.dead-letter-critical-threshold','core.observability.recovery-metrics.dead-letter-warning-threshold','core.observability.recovery-metrics.delayed-requeue-critical-threshold','core.observability.recovery-metrics.delayed-requeue-warning-threshold','core.observability.recovery-metrics.enabled','core.observability.recovery-metrics.history-limit','core.observability.recovery-metrics.recovery-exhausted-critical-threshold','core.observability.recovery-metrics.recovery-exhausted-warning-threshold','core.observability.recovery-metrics.runtime-failure-critical-threshold','core.observability.recovery-metrics.runtime-failure-warning-threshold','core.observability.recovery-metrics.scanner-failure-critical-threshold','core.observability.recovery-metrics.scanner-failure-warning-threshold','core.observability.recovery-metrics.window','core.observability.slow-intake-threshold','core.observability.summary-sample-limit') and status in ('MIGRATED','LEGACY_RETIRED')) then raise exception 'C3R2K_PREMATURE_SINGLE_AUTHORITY_CUTOVER'; end if;
end $$;
